import{r as n,c as t,w as e,e as l,o as a,a as s,b as i,l as c,m as d,j as o,F as u,t as r,v as _,A as f,i as p,V as v}from"./index-DhC8ZmUK.js";import{G as m}from"./GradientButton.OVbFuled.js";import{_ as k}from"./_plugin-vue_export-helper.BCo6x5W8.js";const b=[{id:1,title:"初见倾心",content:"亲爱的{名字}：\n\n还记得我们第一次见面的那一刻吗？阳光正好，微风不燥，你的笑容就这样闯进了我的心里。\n\n从那天起，我的世界多了一份牵挂，多了一份期待。每次想到你，嘴角就会不自觉地上扬。\n\n谢谢你出现在我的生命里，让我知道什么是心动，什么是幸福。\n\n我想牵着你的手，走过春夏秋冬，看遍世间风景。\n\n永远爱你的人\n{署名}\n{日期}"},{id:2,title:"日常甜蜜",content:"亲爱的{名字}：\n\n今天又是一个想你的日子。\n\n早上醒来的第一件事，就是看看手机有没有你的消息。看到你的早安，一整天都会很开心。\n\n你知道吗？和你在一起的每一天，都是我最珍贵的回忆。无论是我们一起吃的那碗面，还是我们一起看的那场电影，都让我觉得无比幸福。\n\n谢谢你一直陪在我身边，包容我的小脾气，给我最温暖的拥抱。\n\n我爱你，比昨天多一点，比明天少一点。\n\n爱你的{署名}\n{日期}"},{id:3,title:"纪念日特辑",content:"亲爱的{名字}：\n\n今天是我们的第{天数}天。\n\n回想我们一起走过的日子，有欢笑，有泪水，有争吵，但更多的是甜蜜和幸福。\n\n谢谢你一直以来的陪伴，谢谢你让我成为最幸福的人。\n\n未来的路还很长，我想和你一起走下去。一起看更多的日落，一起吃更多的美食，一起创造更多属于我们的回忆。\n\n余生请多指教。\n\n永远爱你的{署名}\n{日期}"},{id:4,title:"异地思念",content:"亲爱的{名字}：\n\n又到了一个想你的夜晚。\n\n窗外的月亮很圆，不知道你那边的天气怎么样？有没有好好吃饭？有没有按时睡觉？\n\n虽然我们不能天天见面，但我的心一直和你在一起。每次视频看到你的笑容，所有的疲惫都会消失。\n\n距离不可怕，可怕的是忘记了彼此。但我们不会，因为我们的爱足够坚定。\n\n等我，我很快就去找你。\n\n想你的{署名}\n{日期}"},{id:5,title:"生日祝福",content:"亲爱的{名字}：\n\n生日快乐，我的宝贝！\n\n在这个特别的日子里，我想对你说：谢谢你来到这个世界，谢谢你来到我的身边。\n\n你是上天给我最好的礼物，是我这辈子最幸运遇见的人。\n\n愿你的每一天都充满阳光和欢笑，愿你的每一个梦想都能实现。\n\n我会一直陪在你身边，给你最温暖的爱。\n\n生日快乐，我爱你！\n\n爱你的{署名}\n{日期}"},{id:6,title:"道歉信",content:"亲爱的{名字}：\n\n对不起，这次是我不好。\n\n我知道我让你伤心了，看到你难过的样子，我比谁都心疼。\n\n我不应该{原因}，我承认我错了。请你原谅我，给我一个改正的机会。\n\n你是我最重要的人，我不想因为这件事影响我们的感情。\n\n我保证以后会更加注意，不会再让你难过了。\n\n原谅我好吗？\n\n知错就改的{署名}\n{日期}"},{id:7,title:"告白情书",content:"亲爱的{名字}：\n\n想了很久，还是决定把这些话写下来。\n\n其实从{时间}开始，我就对你有了特别的感觉。你的笑容，你的声音，你的一举一动，都深深地印在了我的心里。\n\n我喜欢你，不是一时冲动，而是经过深思熟虑后的决定。\n\n我喜欢你的善良，你的温柔，你的可爱，你的一切。\n\n如果你也对我有同样的感觉，请给我一个机会，让我照顾你，保护你。\n\n期待你的回复。\n\n喜欢你的{署名}\n{日期}"},{id:8,title:"感恩有你",content:"亲爱的{名字}：\n\n今天想写一封信，谢谢你一直以来的付出。\n\n谢谢你在我难过时安慰我，在我开心时陪我笑，在我迷茫时给我方向。\n\n你总是默默为我做很多，虽然有时候不说，但我都看在眼里，记在心里。\n\n有你在我身边，我觉得自己是世界上最幸福的人。\n\n未来的日子，换我来照顾你，给你更多的爱和温暖。\n\n感恩有你，永远爱你。\n\n爱你的{署名}\n{日期}"},{id:9,title:"未来憧憬",content:"亲爱的{名字}：\n\n有时候我会想象我们的未来。\n\n我想和你一起布置我们的小家，墙上挂满我们的合照。每天早上醒来，第一眼看到的就是你。\n\n我想和你一起养一只猫或狗，周末的时候一起去公园散步。\n\n我想和你一起旅行，去我们都没去过的地方，创造属于我们的回忆。\n\n我想和你一起慢慢变老，直到白发苍苍，还能牵着你的手说：我爱你。\n\n这些憧憬，因为有你，都变得可能。\n\n期待未来的{署名}\n{日期}"},{id:10,title:"小情话合集",content:"亲爱的{名字}：\n\n1. 你知道你和星星的区别吗？星星在天上，你在我心里。\n\n2. 我这一生遇到过很多美好的东西，但都不及你。\n\n3. 我想变成你的手机，被你捧在手里，看在眼里，记在心里。\n\n4. 遇见你之前，我没想过结婚；遇见你之后，我没想过别人。\n\n5. 你是年少的欢喜，也是余生的甜蜜。\n\n6. 我希望有个如你一般的人，如山间清爽的风，如古城温暖的光。\n\n7. 我想把世界上最好的都给你，却发现世界上最好的就是你。\n\n8. 你是我所有的心动和不安，也是我所有的温柔和期待。\n\n9. 我希望余生都是你，余生都是你。\n\n10. 我爱你，不只是说说而已。\n\n永远爱你的{署名}\n{日期}"}],g=k({__name:"love-letter",setup(k){const g=n(null),x=n(""),h=()=>{_(`letter_${g.value.id}`,x.value),f({title:"保存成功",icon:"success"})};return(n,_)=>{const f=p,k=l,j=v;return a(),t(k,{class:"letter-page"},{default:e(()=>[g.value?(a(),t(k,{key:1,class:"letter-detail"},{default:e(()=>[s(k,{class:"detail-header"},{default:e(()=>[s(f,{class:"back-btn",onClick:_[0]||(_[0]=n=>g.value=null)},{default:e(()=>[i("← 返回")]),_:1}),s(f,{class:"letter-title"},{default:e(()=>[i(r(g.value.title),1)]),_:1})]),_:1}),s(k,{class:"letter-content card"},{default:e(()=>[s(j,{class:"letter-text",modelValue:x.value,"onUpdate:modelValue":_[1]||(_[1]=n=>x.value=n),"auto-height":""},null,8,["modelValue"])]),_:1}),s(k,{class:"letter-actions"},{default:e(()=>[s(m,{text:"保存",onClick:h})]),_:1})]),_:1})):(a(),t(k,{key:0,class:"letter-list"},{default:e(()=>[s(f,{class:"page-title"},{default:e(()=>[i("情书模板")]),_:1}),(a(!0),c(u,null,d(o(b),n=>(a(),t(k,{key:n.id,class:"letter-card card",onClick:t=>(n=>{g.value=n,x.value=n.content})(n)},{default:e(()=>[s(f,{class:"letter-title"},{default:e(()=>[i(r(n.title),1)]),_:2},1024),s(f,{class:"letter-preview"},{default:e(()=>[i(r(n.content.substring(0,50))+"...",1)]),_:2},1024)]),_:2},1032,["onClick"]))),128))]),_:1}))]),_:1})}}},[["__scopeId","data-v-0b4d66ab"]]);export{g as default};
